package tn.smartuniversity.auth;
import jakarta.validation.constraints.*; import java.util.Map; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import tn.smartuniversity.security.JwtService; import tn.smartuniversity.user.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public record RegisterRequest(@NotBlank String firstName,@NotBlank String lastName,@Email @NotBlank String email,@Size(min=8) String password,@NotBlank String role,String studentId,String employeeId){} public record LoginRequest(@Email @NotBlank String email,@NotBlank String password){} public record UserDto(String id,String firstName,String lastName,String email,String role,String studentId,String employeeId){} public record AuthResponse(String token,UserDto user){} private UserDto dto(AppUser u){return new UserDto(u.getId(),u.getFirstName(),u.getLastName(),u.getEmail(),u.getRole(),u.getStudentId(),u.getEmployeeId());} @PostMapping("/register") public ResponseEntity<?> register(@jakarta.validation.Valid @RequestBody RegisterRequest r){String role=r.role().toLowerCase();if(!role.equals("student")&&!role.equals("professor"))return ResponseEntity.badRequest().body(Map.of("message","Only student and professor self-registration is allowed."));if(users.existsByEmail(r.email().toLowerCase()))return ResponseEntity.status(409).body(Map.of("message","Email already registered"));AppUser u=new AppUser();u.setFirstName(r.firstName());u.setLastName(r.lastName());u.setEmail(r.email().toLowerCase());u.setPassword(encoder.encode(r.password()));u.setRole(role);u.setStudentId(r.studentId());u.setEmployeeId(r.employeeId());users.save(u);return ResponseEntity.status(201).body(new AuthResponse(jwt.generate(u),dto(u)));} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody LoginRequest r){AppUser u=users.findByEmail(r.email().toLowerCase()).orElse(null);if(u==null||!encoder.matches(r.password(),u.getPassword())||!u.isEnabled())return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));return ResponseEntity.ok(new AuthResponse(jwt.generate(u),dto(u)));} @GetMapping("/me") public ResponseEntity<?> me(org.springframework.security.core.Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow();return ResponseEntity.ok(dto(u));} }
